import csv,html,json
from pathlib import Path
BASE=Path(__file__).resolve().parent
PROJECT=Path('C:/DoAn_H20_2/OpenMeteo_H2O_3_ThanhPho')
run_id=json.loads((PROJECT/'LATEST_RUN.json').read_text(encoding='utf-8-sig'))['run_id']
R=PROJECT/'runs'/run_id

def rows(name):
    with (R/name).open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def n(value):return f'{float(value):,.2f}'.replace(',','~').replace('.',',').replace('~','.')
def count(name):return len(rows(name))
def table(headers,data):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in data)+'</tbody></table></div>'
def fig(name,title,caption):
    assert (R/'figures'/name).is_file()
    return f'<figure><h3>{title}</h3><a href="/figures/{name}" target="_blank" rel="noopener"><img loading="lazy" src="/figures/{name}" alt="{title}"></a><figcaption>{caption} Bấm biểu đồ để xem ảnh gốc.</figcaption></figure>'
def pair(left,right):return '<div class="pair">'+left+right+'</div>'
quality=rows('reports/hourly_quality.csv'); splits=rows('reports/split_ranges.csv'); coverage=rows('reports/algorithm_coverage.csv'); metrics=rows('metrics/family_comparison_test.csv')
before={r['']:r for r in rows('reports/before_describe.csv')}; after={r['']:r for r in rows('reports/after_daily_describe.csv')}
hourly=sum(int(r['rows']) for r in quality); daily=count('processed/daily_clean.csv'); samples=count('features/supervised_next_day.csv')
assert hourly==int(float(before['count']['us_aqi (USAQI)'])) and daily==int(float(after['count']['aqi']))
assert sum(int(r['rows']) for r in splits)<=samples
variables=[('PM2.5','pm2_5 (μg/m³)','pm2_5','µg/m³'),('PM10','pm10 (μg/m³)','pm10','µg/m³'),('CO','carbon_monoxide (μg/m³)','co','µg/m³'),('NO₂','nitrogen_dioxide (μg/m³)','no2','µg/m³'),('SO₂','sulphur_dioxide (μg/m³)','so2','µg/m³'),('O₃','ozone (μg/m³)','o3','µg/m³'),('US AQI','us_aqi (USAQI)','aqi','điểm')]
def describe_table(description, stage):
    return '<article><h3>'+stage+'</h3>'+table(['Biến','TB','ĐLC','Min','Q1','Trung vị','Q3','Max'],[[label]+[n(description[k][raw if description is before else clean]) for k in ['mean','std','min','25%','50%','75%','max']] for label,raw,clean,unit in variables])+'</article>'
stats=pair(describe_table(before,'Trước xử lý · theo giờ'),describe_table(after,'Sau xử lý · theo ngày'))
audit_rows=rows('reports/quality_before_after.csv')
audit_by_stage={r['stage']:r for r in audit_rows}
quality_audit=table(['Kiểm tra','Trước · theo giờ','Sau làm sạch · theo giờ','Sau tổng hợp · theo ngày'],[[label]+[audit_by_stage[stage][key] for stage in ['before_hourly','after_hourly','after_daily']] for label,key in [('Số dòng','rows'),('Ô thiếu trong 7 biến','missing_original_cells'),('Ô thiếu sau chuyển số','missing_numeric_cells'),('Giá trị âm','negative_cells'),('Giá trị vô hạn','infinite_cells'),('Bản ghi trùng khóa','duplicate_keys')]])

base=next(r for r in metrics if r['family']=='Baseline'); leader=next(r for r in metrics if r['family']=='StackedEnsemble')
def metric_card(title,r):return '<article><h3>'+title+'</h3><div class="metric">MAE <strong>'+n(r['mae'])+'</strong>RMSE <strong>'+n(r['rmse'])+'</strong>R² <strong>'+n(r['r2'])+'</strong></div></article>'
content=f'''<div class="eyebrow">Khai phá dữ liệu · Quy trình huấn luyện</div><h1>Từ dữ liệu gốc <em>đến mô hình dự báo</em></h1><p class="lead">Các thống kê và biểu đồ thật từ lần chạy Colab <code>{run_id}</code>. So sánh cùng cấp, giữ rõ đơn vị và tập đánh giá.</p>
<div class="kpis"><article><span>Bản ghi theo giờ</span><strong>{hourly:,}</strong></article><article><span>Bản ghi theo ngày</span><strong>{daily:,}</strong></article><article><span>Mẫu dự báo t → t+1</span><strong>{samples:,}</strong></article><article><span>Đặc trưng đầu vào</span><strong>21</strong></article></div>
<div class="anchors"><a href="#eda">01 · Trước / sau xử lý</a><a href="#training">02 · Dữ liệu train</a><a href="#results">03 · Sau train</a></div>
<section><h2>Nguồn và phạm vi dữ liệu</h2><p><strong>Hà Nội · Đà Nẵng · TP. Hồ Chí Minh — 01/01/2023 đến 04/10/2026.</strong> Múi giờ UTC+7. Dữ liệu CAMS qua Open-Meteo là ước tính mô hình khí quyển tại ô lưới đại diện, không phải số đo trạm hay toàn bộ địa bàn thành phố.</p><p>Đích dự báo: <strong>US AQI trung bình ngày kế tiếp</strong>. File dự báo nguồn 05–09/10/2026 được lưu riêng, không đưa vào huấn luyện hoặc test. <a href="https://open-meteo.com/en/docs/air-quality-api" target="_blank" rel="noopener">Nguồn Open-Meteo</a></p></section>
<section id="eda"><div class="eyebrow">01 · Khai phá & tiền xử lý</div><h2>Trước và sau tiền xử lý</h2>
{pair('<article><h3>Trước xử lý · dữ liệu theo giờ</h3><p>98.856 dòng, 3 thành phố, 7 biến chất lượng không khí. Giữ nguyên file CSV tải xuống.</p><p><strong>0 giá trị thiếu; 0 giờ thiếu</strong> trong báo cáo chất lượng. Kiểm tra phân bố, khoảng giá trị và biến động theo thời gian.</p></article>','<article><h3>Sau xử lý · dữ liệu theo ngày</h3><p>4.119 dòng ngày–thành phố. Chuẩn hóa tên cột, kiểu số và thời gian; kiểm tra giá trị âm và bản ghi trùng.</p><p>Tổng hợp trung bình 24 giờ, AQI cực đại và độ lệch chuẩn PM2.5. Không loại điểm cao chỉ vì là ngoại lệ; không điền từ dữ liệu tương lai.</p></article>')}
{table(['Thành phố','Số dòng theo giờ','Giờ thiếu','Giá trị thiếu'],[[r['city'],r['rows'],r['missing_hours'],r['missing_values']] for r in quality])}
{pair(fig('02_before_missing_boxplot.png','Trước xử lý · thiếu dữ liệu & phân bố','Biểu đồ theo giờ trước chuẩn hóa.'),fig('04_after_missing_boxplot.png','Sau xử lý · thiếu dữ liệu & phân bố','Biểu đồ dữ liệu sau xử lý.'))}
<h3>Kiểm tra chất lượng dữ liệu trước / sau</h3>{quality_audit}<p class="note">Số dòng giảm khi tổng hợp giờ thành ngày không có nghĩa bị xóa dữ liệu. Nếu chỉ số chất lượng đều bằng 0, dữ liệu đã đầy đủ ngay từ nguồn; không khẳng định đã sửa lỗi không tồn tại.</p><h3>Thống kê mô tả trên cùng nhóm biến</h3><p class="note">ĐLC = độ lệch chuẩn; Q1/Q3 = tứ phân vị 25%/75%. Hai bảng có độ phân giải khác nhau: theo giờ và trung bình ngày. Min/max thường thay đổi do tổng hợp, không phải bằng chứng mô hình tốt hơn. Nồng độ dùng µg/m³; AQI dùng điểm.</p>{stats}
{fig('04_before_after_monthly_aqi.png','Xu hướng trước / sau · cùng mốc tháng','Hai phía cùng đơn vị, mốc thời gian và giới hạn trục. Phía sau dùng số giờ làm trọng số khi tổng hợp trung bình ngày về tháng.')}
{fig('04_after_daily_aqi.png','Chi tiết chuỗi ngày sau xử lý','Chuỗi ngày được dùng tạo đặc trưng dự báo; bổ sung cho đối chiếu tháng phía trên.')}
{fig('04_before_after_aqi_histogram.png','Histogram trước / sau xử lý','Dùng cùng 45 khoảng chia, cùng trục AQI và mật độ xác suất để đối chiếu hai tập có số mẫu khác nhau; theo giờ so với trung bình ngày.')}
<div id="correlation"><h3>Đối chiếu tương quan trước / sau xử lý</h3><p class="note">Cùng 7 biến, cùng thứ tự, hệ số Pearson và thang màu −1 đến 1. Bên trái là dữ liệu gốc theo giờ; bên phải là dữ liệu tổng hợp theo ngày. Khác biệt có thể do tổng hợp thời gian; tương quan không chứng minh nhân quả.</p>
{pair(fig('02_before_correlation.png','Tương quan trước xử lý','Tính trực tiếp từ 98.856 dòng gốc theo giờ; không làm sạch hoặc tổng hợp trước khi tính.'),fig('04_after_correlation.png','Tương quan sau xử lý','Tính từ 4.119 dòng ngày–thành phố sau tiền xử lý và tổng hợp 24 giờ.'))}</div></section>
<section id="training"><div class="eyebrow">02 · Trước khi train</div><h2>Đặc trưng và chia dữ liệu theo thời gian</h2><p>21 đầu vào gồm thành phố, các chỉ số ngày t, độ trễ AQI 1/2/3/7 ngày, trung bình trượt 3/7 ngày và thông tin lịch của ngày cần dự báo. Nhãn là AQI ngày t+1. Chỉ dùng dữ liệu đã có đến ngày t.</p><p>Từ {samples:,} mẫu, dùng {sum(int(r['rows']) for r in splits):,} mẫu trong 5 tập; bỏ mẫu tại ranh giới để tránh chồng ngày giữa các tập. Không chia ngẫu nhiên chuỗi thời gian.</p>
{table(['Tập dữ liệu','Số mẫu','Ngày đầu vào bắt đầu','Ngày nhãn bắt đầu','Ngày nhãn kết thúc'],[[r['split'],r['rows'],r['input_start'][:10],r['target_start'][:10],r['target_end'][:10]] for r in splits])}
{fig('06_split_sizes.png','Quy mô các tập dữ liệu','Train để học; early_stop để dừng; blend để học kết hợp; validation chọn model; test đánh giá cuối.')}
<p><strong>AutoML mở toàn bộ họ thuật toán được hỗ trợ trong cấu hình này</strong>, không giới hạn GLM/GBM/DRF. Lần chạy sinh {sum(int(r['models']) for r in coverage)} mô hình; các họ được thử thực tế:</p>{table(['Họ thuật toán','Số mô hình'],[[r['family'],r['models']] for r in coverage])}</section>
<section id="results"><div class="eyebrow">03 · Sau khi train</div><h2>Baseline và model — cùng 408 mẫu test</h2><p>Baseline lấy AQI ngày hôm nay làm dự báo ngày kế tiếp. Model được chọn bằng validation rồi đánh giá trên test; không chọn lại model dựa vào test. MAE và RMSE càng thấp càng tốt.</p>
{pair(metric_card('Mốc trước train · Persistence baseline',base),metric_card('Sau train · H2O StackedEnsemble',leader))}
<p class="note"><strong>MAE giảm {n((1-float(leader['mae'])/float(base['mae']))*100)}%; RMSE giảm {n((1-float(leader['rmse'])/float(base['rmse']))*100)}%</strong> so với baseline trên cùng tập test.</p>
{table(['Mô hình','MAE (điểm AQI)','RMSE (điểm AQI)','R²'],[[r['family'],n(r['mae']),n(r['rmse']),n(r['r2'])] for r in metrics])}
{pair(fig('10_test_comparison_scatter.png','Giá trị thực của dataset ↔ dự báo','So sánh dự báo trên tập test; “thực” ở đây là giá trị CAMS trong dataset.'),fig('10_test_residuals.png','Phân bố sai số sau train','Quan sát độ lệch, độ phân tán và sai số lớn.'))}
{fig('10_test_timeseries_cities.png','Kết quả test theo thời gian ở 3 thành phố','Đối chiếu đường dự báo với dữ liệu test theo từng thành phố.')}
<h3>Sai số theo thành phố</h3>{table(['Thành phố','MAE','RMSE','R²'],[[r['city'],n(r['mae']),n(r['rmse']),n(r['r2'])] for r in rows('metrics/test_by_city.csv')])}
<p class="note">Các kết quả đánh giá khả năng dự báo chuỗi CAMS, không xác nhận độ chính xác với trạm đo thực tế. Giá trị trung bình ngày có thể che khuất giờ ô nhiễm cao.</p></section><footer>Biểu đồ và số liệu đọc từ reports / figures / metrics của Colab. Trang tổng quan không sửa CSV gốc, không huấn luyện lại và không thay model dự báo.</footer>'''
